import{c as r,Q as a,j as e,m as l}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"客户端服务端与MVC风格","description":"","frontmatter":{"title":"客户端服务端与MVC风格"},"headers":[],"relativePath":"综合知识/架构设计/架构风格与模式/常用架构风格/客户端服务端与MVC风格.md","filePath":"综合知识/架构设计/架构风格与模式/常用架构风格/客户端服务端与MVC风格.md","lastUpdated":null}'),o={name:"综合知识/架构设计/架构风格与模式/常用架构风格/客户端服务端与MVC风格.md"};function d(i,t,s,n,h,b){return a(),e("div",null,[...t[0]||(t[0]=[l('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 两层 C/S 架构及缺点</li><li>[ ] 三层 C/S / B/S 架构</li><li>[ ] 富互联网应用（RIA）</li><li>[ ] MVC / MVP / MVVM 对比</li><li>[ ] 专家系统（ES）vs 决策支持系统（DSS）</li><li>[ ] 架构风格与系统性能关系</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="两层-c-s-架构" tabindex="-1">两层 C/S 架构 <a class="header-anchor" href="#两层-c-s-架构" aria-label="Permalink to &quot;两层 C/S 架构&quot;">​</a></h3><ul><li>客户端和服务器都有处理功能，现已不常用</li><li>缺点：开发成本高、客户端复杂、维护升级困难、安全性问题、难以复用</li></ul><h3 id="三层-c-s-架构" tabindex="-1">三层 C/S 架构 <a class="header-anchor" href="#三层-c-s-架构" aria-label="Permalink to &quot;三层 C/S 架构&quot;">​</a></h3><ul><li>表示层（客户机）+ 功能层（应用服务器）+ 数据层（数据库服务器）</li><li>将处理功能独立出来</li></ul><table tabindex="0"><thead><tr><th>优点</th></tr></thead><tbody><tr><td>各层逻辑独立，提高可维护性和可扩展性</td></tr><tr><td>允许灵活选用相应平台和硬件</td></tr><tr><td>各层可并行开发</td></tr><tr><td>功能层隔离表示层与数据层，安全管理更可控</td></tr></tbody></table><blockquote><p>🎯 三层 C/S 关键在于<strong>各层之间通信效率</strong>。</p></blockquote><h3 id="三层-b-s-架构" tabindex="-1">三层 B/S 架构 <a class="header-anchor" href="#三层-b-s-架构" aria-label="Permalink to &quot;三层 B/S 架构&quot;">​</a></h3><ul><li>三层 C/S 变种：客户端→浏览器，应用服务器→WEB 服务器</li><li>又称 <strong>0 客户端架构</strong></li><li>缺点：动态页面支持弱、安全性难控制、响应速度低、数据交互性不强</li></ul><h3 id="富互联网应用-ria" tabindex="-1">富互联网应用（RIA） <a class="header-anchor" href="#富互联网应用-ria" aria-label="Permalink to &quot;富互联网应用（RIA）&quot;">​</a></h3><ul><li>本质仍是 0 客户端，借助高速网速实现必要插件本地快速缓存</li><li>类比：小程序</li></ul><hr><h3 id="mvc-架构" tabindex="-1">MVC 架构 <a class="header-anchor" href="#mvc-架构" aria-label="Permalink to &quot;MVC 架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>职责</th></tr></thead><tbody><tr><td><strong>Controller</strong>（控制器）</td><td>处理用户交互，控制输入，向 Model 发数据</td></tr><tr><td><strong>Model</strong>（模型）</td><td>业务数据和业务逻辑</td></tr><tr><td><strong>View</strong>（视图）</td><td>数据显示，不进行业务处理</td></tr></tbody></table><h3 id="mvp" tabindex="-1">MVP <a class="header-anchor" href="#mvp" aria-label="Permalink to &quot;MVP&quot;">​</a></h3><ul><li>Controller → <strong>Presenter</strong>（呈现）</li><li><strong>完全切断 View 与 Model 的联系</strong>，由 Presenter 充当桥梁</li><li>View 非常薄（被动视图），Presenter 非常厚</li></ul><h3 id="mvvm" tabindex="-1">MVVM <a class="header-anchor" href="#mvvm" aria-label="Permalink to &quot;MVVM&quot;">​</a></h3><ul><li>低耦合：View 独立于 Model，一个 ViewModel 绑定多个 View</li><li>可重用性：视图逻辑在 ViewModel</li><li>独立开发：开发人员业务逻辑，设计人员页面</li><li>可测试：针对 ViewModel 编写测试</li></ul><hr><h3 id="专家系统-es-vs-决策支持系统-dss" tabindex="-1">专家系统（ES）vs 决策支持系统（DSS） <a class="header-anchor" href="#专家系统-es-vs-决策支持系统-dss" aria-label="Permalink to &quot;专家系统（ES）vs 决策支持系统（DSS）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>解决问题类型</th><th>核心特征</th><th>常用架构风格</th></tr></thead><tbody><tr><td><strong>ES</strong></td><td>依赖领域知识推理</td><td>能<strong>解释推理过程</strong></td><td>规则系统</td></tr><tr><td><strong>DSS</strong></td><td><strong>半结构化</strong>问题</td><td>辅助决策而非替代人</td><td>规则系统</td></tr></tbody></table><blockquote><p>⚠️ ES 根本区别于一般系统在于：<strong>解释推理过程</strong>。DSS 处理<strong>半结构化</strong>问题。</p></blockquote><hr><h3 id="🎯-架构风格与系统性能-高频考点" tabindex="-1">🎯 架构风格与系统性能（高频考点） <a class="header-anchor" href="#🎯-架构风格与系统性能-高频考点" aria-label="Permalink to &quot;🎯 架构风格与系统性能（高频考点）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风格</th><th>对性能的影响</th><th>原因</th></tr></thead><tbody><tr><td><strong>层次化架构</strong></td><td>层次越多性能<strong>越差</strong></td><td>每次调用需穿过多层</td></tr><tr><td><strong>隐式调用（事件驱动）</strong></td><td>可<strong>提高</strong>性能</td><td>事件可并行处理</td></tr><tr><td><strong>面向对象</strong></td><td><strong>降低</strong>性能（引入对象管理层）</td><td>增加间接调用层次</td></tr><tr><td><strong>解释器</strong></td><td>预先编译部分代码可提高</td><td>减少运行时解释开销</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：<strong>&quot;面向对象风格可通过引入对象管理层提高系统性能&quot;是错误的</strong>（实际会降低）。</p></blockquote>',28)])])}const g=r(o,[["render",d]]);export{c as __pageData,g as default};
